import React, { useEffect, useState } from 'react';
import '../css/style.css';
import { Link } from 'react-router-dom';
import { getAuth, GoogleAuthProvider, signInWithPopup } from 'firebase/auth';
import '../firebase';

const Header = () => {
  const [userEmail, setUserEmail] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [emailInput, setEmailInput] = useState('');
  const [passwordInput, setPasswordInput] = useState('');
  const [emailError, setEmailError] = useState('');
  const [isRegistering, setIsRegistering] = useState(false);

  const API_URL = 'https://laba-kvp4.onrender.com';

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      fetch(`${API_URL}/profile`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
        .then((res) => {
          if (!res.ok) throw new Error('Unauthorized');
          return res.json();
        })
        .then((data) => {
          setUserEmail(data.email);
        })
        .catch(() => {
          localStorage.removeItem('token');
          setUserEmail(null);
        });
    }
  }, []);

  const validateEmail = (email) => {
    const re = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i;
    return re.test(email);
  };

  const handleAuth = async () => {
    if (!validateEmail(emailInput)) {
      setEmailError('Введіть коректний email.');
      return;
    }
    if (!passwordInput) {
      setEmailError('Введіть пароль.');
      return;
    }

    try {
      const endpoint = isRegistering ? '/register' : '/login';
      const response = await fetch(`${API_URL}${endpoint}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          email: emailInput,
          password: passwordInput,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Сталася помилка.');
      }

      localStorage.setItem('token', data.token);

      const profileRes = await fetch(`${API_URL}/profile`, {
        headers: {
          Authorization: `Bearer ${data.token}`,
        },
      });

      const profile = await profileRes.json();
      setUserEmail(profile.email);

      setShowModal(false);
      setEmailInput('');
      setPasswordInput('');
      setEmailError('');
      window.location.reload();
    } catch (error) {
      setEmailError(error.message);
    }
  };

  const handleGoogleLogin = async () => {
    try {
      const provider = new GoogleAuthProvider();
      const auth = getAuth();

      const result = await signInWithPopup(auth, provider);
      const idToken = await result.user.getIdToken();

      const response = await fetch(`${API_URL}/google-login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ idToken }),
      });

      const data = await response.json();

      if (!response.ok) throw new Error(data.error || 'Помилка при вході');

      localStorage.setItem('token', data.token);

      const profileRes = await fetch(`${API_URL}/profile`, {
        headers: {
          Authorization: `Bearer ${data.token}`,
        },
      });

      const profile = await profileRes.json();
      setUserEmail(profile.email);
      setShowModal(false);
      window.location.reload();
    } catch (error) {
      console.error('Google login failed', error);
      setEmailError('Не вдалося увійти через Google');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    setUserEmail(null);
    window.location.reload();
  };

  return (
    <header className="header" id="header">
      <nav className="nav container">
        <Link to="/" className="nav__logo">
          <img src={process.env.PUBLIC_URL + '/images/Logo.png'} alt="Logo" />
          ЖивиТут
        </Link>

        <div className="nav__menu">
          <ul className="nav__list">
            <li className="nav__item">
              <Link to="/" className="nav__link">
                <i className="bx bx-home-alt-2"></i>
                <span>Головна</span>
              </Link>
            </li>
            <li className="nav__item">
              <Link to="/available" className="nav__link">
                <i className="bx bx-building-house"></i>
                <span>Доступні квартири</span>
              </Link>
            </li>
            <li className="nav__item">
              <Link to="/booked" className="nav__link">
                <i className="bx bx-bookmark"></i>
                <span>Мої бронювання</span>
              </Link>
            </li>
            <li className="nav__item">
              <Link to="/" className="nav__link">
                <i className="bx bx-phone"></i>
                <span>Контакти</span>
              </Link>
            </li>
          </ul>
        </div>

        {!userEmail ? (
          <button className="button nav__button" onClick={() => setShowModal(true)}>
            Увійти / Зареєструватися
          </button>
        ) : (
          <button className="button nav__button" onClick={handleLogout}>
            Вийти
          </button>
        )}
      </nav>

      {showModal && (
        <div className="modal">
          <div className="modal-content">
            <h2 className="model-header">{isRegistering ? 'Реєстрація' : 'Вхід'}</h2>
            <input
              type="email"
              placeholder="Email"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
            />
            <input
              type="password"
              placeholder="Пароль"
              value={passwordInput}
              onChange={(e) => setPasswordInput(e.target.value)}
            />
            {emailError && <p className="error-text">{emailError}</p>}
            <div className="modal-buttons">
              <button onClick={handleAuth} className="button">
                {isRegistering ? 'Зареєструватися' : 'Увійти'}
              </button>
              <button
                onClick={() => {
                  setShowModal(false);
                  setEmailError('');
                }}
                className="button button--gray"
              >
                Скасувати
              </button>
            </div>
            <p className="auth-switch">
              {isRegistering ? 'Вже маєте акаунт?' : 'Немає акаунта?'}{' '}
              <span className="auth-toggle" onClick={() => setIsRegistering(!isRegistering)}>
                {isRegistering ? 'Увійти' : 'Зареєструватися'}
              </span>
            </p>
            <div className="google-login">
              <p>Або {isRegistering ? 'зареєструйтеся' : 'увійдіть'} через Google</p>
              <button className="google-button" onClick={handleGoogleLogin}>
                <img src={process.env.PUBLIC_URL + '/images/google.png'} alt="Google" />
                {isRegistering ? 'Зареєструватися' : 'Увійти'} з Google
              </button>
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;
