import React, { useEffect, useRef, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Swiper from 'swiper';
import { Navigation, Pagination, Autoplay } from 'swiper/modules';
import 'swiper/swiper-bundle.css';
import 'leaflet-gesture-handling';
import Footer from '../components/Footer';
import Header from '../components/Header';
import DatePicker from 'react-datepicker';
import { registerLocale } from 'react-datepicker';
import uk from 'date-fns/locale/uk';
import 'react-datepicker/dist/react-datepicker.css';
import ApartmentMap from '../components/ApartmentMap';

registerLocale('uk', uk);
Swiper.use([Navigation, Pagination, Autoplay]);

const ApartmentDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();

  const [apartment, setApartment] = useState(null);
  const [modalImage, setModalImage] = useState('');
  const [isImageModalOpen, setIsImageModalOpen] = useState(false);
  const [isBookingModalOpen, setIsBookingModalOpen] = useState(false);
  const swiperRef = useRef(null);

  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);
  const [bookedDates, setBookedDates] = useState([]);

  const [reviews, setReviews] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [totalReviews, setTotalReviews] = useState(0);
  const [isLoadingReviews, setIsLoadingReviews] = useState(false);
  const reviewsPerPage = 10; // Кількість відгуків на сторінці

  const [reviewText, setReviewText] = useState('');
  const [hasBooked, setHasBooked] = useState(false);
  const [reviewName, setReviewName] = useState('');
  const [editingReviewId, setEditingReviewId] = useState(null);
  const [editingText, setEditingText] = useState('');
  const [user, setUser] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // Перевірка автентифікації користувача при завантаженні сторінки
  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      fetch('https://laba-kvp4.onrender.com/profile', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
        .then((res) => res.json())
        .then((data) => {
          if (data && data.email) {
            setUser(data);
            setIsAuthenticated(true);
          } else {
            setUser(null);
            setIsAuthenticated(false);
            localStorage.removeItem('token');
          }
        })
        .catch(() => {
          setUser(null);
          setIsAuthenticated(false);
          localStorage.removeItem('token');
        });
    }
  }, []);

  useEffect(() => {
    const fetchApartment = async () => {
      try {
        const response = await fetch(`https://laba-kvp4.onrender.com/flats/${id}`);
        if (!response.ok) {
          throw new Error('Квартира не знайдена');
        }
        const apartmentData = await response.json();
        setApartment(apartmentData);
      } catch (err) {
        console.error('Помилка при завантаженні квартири:', err);
      }
    };

    if (id) {
      fetchApartment();
    }
  }, [id]);

  useEffect(() => {
    if (!apartment) return;

    const fetchBookings = async () => {
      try {
        const response = await fetch(
          `https://laba-kvp4.onrender.com/bookings/flat/${apartment.id}`
        );
        const data = await response.json();

        const currentFlatBookings = data.map((b) => ({
          start: new Date(b.start),
          end: new Date(b.end),
        }));

        setBookedDates(currentFlatBookings);
      } catch (err) {
        console.error('Помилка при завантаженні бронювань:', err);
      }
    };

    fetchBookings();
    fetchReviews(1); // При першому завантаженні отримуємо першу сторінку відгуків

    setTimeout(() => {
      swiperRef.current = new Swiper('.mySwiper', {
        navigation: {
          nextEl: '.swiper-button-next',
          prevEl: '.swiper-button-prev',
        },
        pagination: {
          el: '.swiper-pagination',
          clickable: true,
        },
        autoplay: {
          delay: 5000,
          disableOnInteraction: false,
        },
      });
    }, 0);
  }, [apartment, id]);

  // Функція для завантаження відгуків з пагінацією
  const fetchReviews = async (page = 1) => {
    if (!id) return;

    setIsLoadingReviews(true);
    try {
      const response = await fetch(
        `https://laba-kvp4.onrender.com/reviews/${id}?page=${page}&limit=${reviewsPerPage}`
      );

      if (!response.ok) {
        throw new Error('Не вдалося завантажити відгуки');
      }

      const data = await response.json();

      setReviews(data.reviews);
      setTotalPages(data.pagination.totalPages);
      setTotalReviews(data.pagination.totalReviews);
      setCurrentPage(data.pagination.currentPage);
    } catch (err) {
      console.error('Помилка при завантаженні відгуків:', err);
    } finally {
      setIsLoadingReviews(false);
    }
  };

  // Обробник зміни сторінки відгуків
  const handlePageChange = (newPage) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      fetchReviews(newPage);

      // Прокручуємо до розділу відгуків при зміні сторінки
      document.getElementById('reviews').scrollIntoView({ behavior: 'smooth' });
    }
  };

  const handleBooking = async () => {
    if (startDate && endDate) {
      const isOverlapping = bookedDates.some(({ start, end }) => {
        return startDate <= end && endDate >= start;
      });

      if (isOverlapping) {
        alert('Обрані дати перетинаються з уже існуючим бронюванням.');
        return;
      }

      const token = localStorage.getItem('token');
      if (!token) {
        alert('Вам потрібно увійти, щоб забронювати.');
        return;
      }

      try {
        const res = await fetch('https://laba-kvp4.onrender.com/bookings', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            flatId: apartment.id,
            start: startDate.toISOString(),
            end: endDate.toISOString(),
          }),
        });

        const data = await res.json();

        if (!res.ok) {
          alert(data.error || 'Помилка при бронюванні');
          return;
        }

        setBookedDates((prev) => [...prev, { start: startDate, end: endDate }]);
        setHasBooked(true);
        alert('Бронювання успішне!');
        setIsBookingModalOpen(false);
        setStartDate(null);
        setEndDate(null);
      } catch (err) {
        console.error('Помилка при збереженні бронювання:', err);
        if (err.message.includes('401')) {
          alert('Час сесії минув. Будь ласка, увійдіть знову.');
          localStorage.removeItem('token');
          setIsAuthenticated(false);
          setUser(null);
        } else {
          alert('Сталася помилка при бронюванні.');
        }
      }
    }
  };

  useEffect(() => {
    const checkUserBooking = async () => {
      if (!isAuthenticated || !apartment || !user) return;

      try {
        const token = localStorage.getItem('token');
        const response = await fetch(
          `https://laba-kvp4.onrender.com/bookings?email=${user.email}`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        if (!response.ok) {
          throw new Error('Не вдалося перевірити бронювання користувача');
        }

        const data = await response.json();
        const userBookings = data.filter((b) => b.flatId === apartment.id);
        setHasBooked(userBookings.length > 0);
      } catch (err) {
        console.error('Помилка при перевірці бронювань користувача:', err);
      }
    };

    checkUserBooking();
  }, [isAuthenticated, apartment, user]);

  const handleAddReview = async () => {
    if (!reviewText.trim() || !reviewName.trim()) return;

    const token = localStorage.getItem('token');
    if (!token) {
      alert('Вам потрібно увійти, щоб залишити відгук.');
      return;
    }

    try {
      const res = await fetch('https://laba-kvp4.onrender.com/reviews', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          flatId: id,
          name: reviewName,
          text: reviewText,
        }),
      });

      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.error || 'Помилка при додаванні відгуку.');
      }

      // Оновлюємо список відгуків (перезавантажуємо першу сторінку)
      fetchReviews(1);
      setCurrentPage(1); // Повертаємось на першу сторінку після додавання відгуку

      setReviewText('');
      setReviewName('');
    } catch (err) {
      console.error('Помилка при збереженні відгуку:', err);
      if (err.message.includes('401')) {
        alert('Час сесії минув. Будь ласка, увійдіть знову.');
        localStorage.removeItem('token');
        setIsAuthenticated(false);
        setUser(null);
      } else {
        alert('Помилка при додаванні відгуку.');
      }
    }
  };

  const handleDeleteReview = async (reviewId) => {
    const token = localStorage.getItem('token');
    if (!token) {
      alert('Вам потрібно увійти, щоб видалити відгук.');
      return;
    }

    try {
      const res = await fetch(`https://laba-kvp4.onrender.com/reviews/${reviewId}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.error || 'Помилка при видаленні відгуку.');
      }

      // Після видалення відгуку оновлюємо поточну сторінку
      fetchReviews(currentPage);

      // Якщо це був останній відгук на сторінці і не перша сторінка, переходимо на попередню
      if (reviews.length === 1 && currentPage > 1) {
        setCurrentPage((prev) => prev - 1);
        fetchReviews(currentPage - 1);
      }
    } catch (err) {
      console.error('Помилка при видаленні відгуку:', err);
      if (err.message.includes('401')) {
        alert('Час сесії минув. Будь ласка, увійдіть знову.');
        localStorage.removeItem('token');
        setIsAuthenticated(false);
        setUser(null);
      } else {
        alert('Помилка при видаленні відгуку.');
      }
    }
  };

  const handleEditReview = async (reviewId, newText) => {
    const token = localStorage.getItem('token');
    if (!token) {
      alert('Вам потрібно увійти, щоб редагувати відгук.');
      return;
    }

    try {
      const res = await fetch(`https://laba-kvp4.onrender.com/reviews/${reviewId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ text: newText }),
      });

      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.error || 'Помилка при редагуванні відгуку.');
      }

      // Оновлюємо список відгуків на поточній сторінці
      fetchReviews(currentPage);
      setEditingReviewId(null);
    } catch (err) {
      console.error('Помилка при редагуванні відгуку:', err);
      if (err.message.includes('401')) {
        alert('Час сесії минув. Будь ласка, увійдіть знову.');
        localStorage.removeItem('token');
        setIsAuthenticated(false);
        setUser(null);
      } else {
        alert('Помилка при оновленні відгуку.');
      }
    }
  };

  const getExcludedDates = () => {
    return bookedDates.flatMap(({ start, end }) => {
      const dates = [];
      let current = new Date(start);
      while (current <= end) {
        dates.push(new Date(current));
        current.setDate(current.getDate() + 1);
      }
      return dates;
    });
  };

  // Компонент пагінації
  const Pagination = () => {
    // Якщо менше 2 сторінок, не показуємо пагінацію
    if (totalPages <= 1) return null;

    const renderPageButtons = () => {
      const buttons = [];
      const maxVisibleButtons = 5; // Максимальна кількість видимих кнопок

      // Розрахунок діапазону сторінок для відображення
      let startPage = Math.max(1, currentPage - Math.floor(maxVisibleButtons / 2));
      let endPage = Math.min(totalPages, startPage + maxVisibleButtons - 1);

      // Корегуємо startPage, якщо endPage досягає максимуму
      if (endPage === totalPages) {
        startPage = Math.max(1, endPage - maxVisibleButtons + 1);
      }

      // Кнопка "Попередня сторінка"
      buttons.push(
        <button
          key="prev"
          className={`pagination-button ${currentPage === 1 ? 'disabled' : ''}`}
          onClick={() => handlePageChange(currentPage - 1)}
          disabled={currentPage === 1}
        >
          <i className="bx bx-chevron-left"></i>
        </button>
      );

      // Якщо startPage > 1, додаємо кнопку першої сторінки і еліпсис
      if (startPage > 1) {
        buttons.push(
          <button
            key="1"
            className={`pagination-number ${currentPage === 1 ? 'active' : ''}`}
            onClick={() => handlePageChange(1)}
          >
            1
          </button>
        );

        if (startPage > 2) {
          buttons.push(
            <span key="ellipsis1" className="pagination-ellipsis">
              ...
            </span>
          );
        }
      }

      // Додаємо номери сторінок
      for (let i = startPage; i <= endPage; i++) {
        buttons.push(
          <button
            key={i}
            className={`pagination-number ${currentPage === i ? 'active' : ''}`}
            onClick={() => handlePageChange(i)}
          >
            {i}
          </button>
        );
      }

      // Якщо endPage < totalPages, додаємо еліпсис і кнопку останньої сторінки
      if (endPage < totalPages) {
        if (endPage < totalPages - 1) {
          buttons.push(
            <span key="ellipsis2" className="pagination-ellipsis">
              ...
            </span>
          );
        }

        buttons.push(
          <button
            key={totalPages}
            className={`pagination-number ${currentPage === totalPages ? 'active' : ''}`}
            onClick={() => handlePageChange(totalPages)}
          >
            {totalPages}
          </button>
        );
      }

      // Кнопка "Наступна сторінка"
      buttons.push(
        <button
          key="next"
          className={`pagination-button ${currentPage === totalPages ? 'disabled' : ''}`}
          onClick={() => handlePageChange(currentPage + 1)}
          disabled={currentPage === totalPages}
        >
          <i className="bx bx-chevron-right"></i>
        </button>
      );

      return buttons;
    };

    return <div className="pagination">{renderPageButtons()}</div>;
  };

  if (!apartment) return <div>Завантаження...</div>;

  const totalPrice =
    startDate && endDate
      ? Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24)) * apartment.price
      : 0;

  return (
    <>
      <Header />

      <main className="main">
        <section className="general section" id="general">
          <div className="general__container container">
            <div className="back__container">
              <a
                href="#"
                className="back__link"
                onClick={(e) => {
                  e.preventDefault();
                  navigate(-1);
                }}
              >
                <i className="bx bx-arrow-back"></i>
                <span>Назад</span>
              </a>
            </div>

            <div className="title__conatiner">
              <h1 className="general__title">{apartment.location}</h1>
            </div>

            <div className="slider__container">
              <div className="swiper mySwiper">
                <div className="swiper-wrapper">
                  {apartment.images?.map((img, idx) => (
                    <div className="swiper-slide" key={idx}>
                      <img
                        src={img.startsWith('http') ? img : process.env.PUBLIC_URL + `/${img}`}
                        className="slider-image"
                        alt="Фото квартири"
                        onClick={() => {
                          setModalImage(
                            img.startsWith('http') ? img : process.env.PUBLIC_URL + `/${img}`
                          );
                          setIsImageModalOpen(true);
                        }}
                      />
                    </div>
                  ))}
                </div>
                <div className="swiper-button-next"></div>
                <div className="swiper-button-prev"></div>
                <div className="swiper-pagination"></div>
              </div>
            </div>

            <div className="info__container">
              <div className="info__item">
                <i className="bx bx-map"></i>
                <span>{apartment.location}</span>
              </div>
              <div className="info__item">
                <i className="bx bx-building"></i>
                <span>{apartment.type}</span>
              </div>
              <div className="info__item">
                <i className="bx bx-area"></i>
                <span>{apartment.size} м²</span>
              </div>
            </div>

            <div className="rent__container">
              <div className="rent__price">
                <p className="rent__price-title">Вартість:</p>
                <span className="rent__price-value">{apartment.price} грн/доба</span>
              </div>
              <div className="rent__button-container">
                <button
                  className="button rent__button"
                  onClick={() => {
                    if (isAuthenticated) {
                      setIsBookingModalOpen(true);
                    }
                  }}
                  style={{
                    backgroundColor: !isAuthenticated ? '#ccc' : '',
                    color: !isAuthenticated ? '#000000' : '',
                    boxShadow: !isAuthenticated ? 'none' : '',
                    fontSize: !isAuthenticated ? '1rem' : '',
                    fontWeight: !isAuthenticated ? '600' : '',
                    cursor: !isAuthenticated ? 'default' : 'pointer',
                  }}
                >
                  {isAuthenticated ? 'Забронювати' : 'Увійдіть щоб забронювати'}
                </button>
              </div>
            </div>
          </div>

          {isImageModalOpen && (
            <div id="imageModal" className="modal" onClick={() => setIsImageModalOpen(false)}>
              <span className="ImgClose" onClick={() => setIsImageModalOpen(false)}>
                <i className="bx bx-x"></i>
              </span>
              <img className="modalImage-content" src={modalImage} alt="Збільшене фото" />
            </div>
          )}

          {isBookingModalOpen && (
            <div className="modal">
              <div className="modal-content">
                <h3>Оберіть дати бронювання</h3>
                <DatePicker
                  locale="uk"
                  selected={startDate}
                  onChange={(dates) => {
                    const [start, end] = dates;
                    setStartDate(start);
                    setEndDate(end);
                  }}
                  startDate={startDate}
                  endDate={endDate}
                  selectsRange
                  excludeDates={getExcludedDates()}
                  minDate={new Date()}
                  placeholderText="Оберіть діапазон дат"
                  dateFormat="dd.MM.yyyy"
                  isClearable
                />
                {startDate && endDate ? <p>Вартість: {totalPrice} грн</p> : <p>Не обрано дат</p>}
                <div className="modal__actions">
                  <button
                    className="modal-button button"
                    onClick={handleBooking}
                    disabled={!startDate || !endDate || startDate.getTime() === endDate.getTime()}
                  >
                    Підтвердити
                  </button>
                  <button
                    className="modal-button button"
                    onClick={() => setIsBookingModalOpen(false)}
                  >
                    Скасувати
                  </button>
                </div>
              </div>
            </div>
          )}
        </section>

        <section className="map section">
          <div className="map__container container">
            <h2 className="map__title">Місце розташування</h2>
            <ApartmentMap
              lat={apartment.lat}
              lng={apartment.lng}
              location={apartment.location}
              price={apartment.price}
            />
          </div>
        </section>

        <section className="description section">
          <div className="description__container container">
            <div className="description__title">
              <h2 className="description__title-text">Опис:</h2>
            </div>
            <div className="description__text">
              <p className="description__text-item">{apartment.description}</p>
            </div>
          </div>
        </section>

        <section className="reviews section" id="reviews">
          <div className="reviews__container container">
            <h2 className="reviews__title">
              Відгуки {totalReviews > 0 ? `(${totalReviews})` : ''}
            </h2>

            {isAuthenticated ? (
              hasBooked ? (
                <div className="review-form">
                  <input
                    type="text"
                    placeholder="Ваше ім'я"
                    value={reviewName}
                    onChange={(e) => setReviewName(e.target.value)}
                    className="name-input"
                  />
                  <input
                    placeholder="Ваш відгук"
                    value={reviewText}
                    onChange={(e) => setReviewText(e.target.value)}
                    className="review-input"
                  />
                  <button className="button review-submit" onClick={handleAddReview}>
                    Залишити відгук
                  </button>
                </div>
              ) : (
                <p className="warning-text">
                  Ви можете залишити відгук лише після бронювання цієї квартири.
                </p>
              )
            ) : (
              <p className="warning-text">Увійдіть, щоб залишити відгук.</p>
            )}

            {isLoadingReviews ? (
              <div className="loading-indicator">Завантаження відгуків...</div>
            ) : (
              <>
                <div className="review-list">
                  {reviews.length === 0 ? (
                    <p className="no-reviews-text">Ще немає відгуків.</p>
                  ) : (
                    reviews.map((review) => {
                      const isMyReview = isAuthenticated && user && review.userEmail === user.email;
                      const isEditing = editingReviewId === review.id;

                      // Функція для форматування дати з різних можливих форматів
                      const formatDate = (dateValue) => {
                        if (!dateValue) return '—';

                        let date;
                        if (typeof dateValue === 'string') {
                          date = new Date(dateValue);
                        } else if (dateValue.seconds) {
                          date = new Date(dateValue.seconds * 1000);
                        } else {
                          return '—';
                        }

                        return date.toLocaleDateString('uk-UA');
                      };

                      return (
                        <div key={review.id} className="review-item">
                          <div className="review-header">
                            <strong>{review.name}</strong>
                            <div className="review-actions-date">
                              {isMyReview && !isEditing && (
                                <div className="review-actions">
                                  <button
                                    className="edit-button"
                                    onClick={() => {
                                      setEditingReviewId(review.id);
                                      setEditingText(review.text);
                                    }}
                                  >
                                    <i className="bx bxs-edit-alt"></i>
                                  </button>
                                  <button
                                    className="delete-button"
                                    onClick={() => handleDeleteReview(review.id)}
                                  >
                                    <i className="bx bxs-trash-alt"></i>
                                  </button>
                                </div>
                              )}
                              <span className="review-date">
                                {review.updatedAt
                                  ? `Оновлено: ${formatDate(review.updatedAt)}`
                                  : formatDate(review.createdAt)}
                              </span>
                            </div>
                          </div>

                          {isEditing ? (
                            <>
                              <input
                                value={editingText}
                                onChange={(e) => setEditingText(e.target.value)}
                                className="review-input"
                              />
                              <button
                                className="button save-button"
                                onClick={() => {
                                  handleEditReview(review.id, editingText);
                                }}
                              >
                                Зберегти
                              </button>
                              <button className="button" onClick={() => setEditingReviewId(null)}>
                                Скасувати
                              </button>
                            </>
                          ) : (
                            <p>{review.text}</p>
                          )}
                        </div>
                      );
                    })
                  )}
                </div>

                {/* Компонент пагінації */}
                {totalReviews > 0 && <Pagination />}
              </>
            )}
          </div>
        </section>
      </main>

      <Footer />
    </>
  );
};

export default ApartmentDetails;
