import { useState, useEffect } from 'react';
import '../css/style.css';
import Footer from '../components/Footer';
import Header from '../components/Header';
import FlatCard from '../components/FlatCard';

const AvailableData = () => {
  const [flats, setFlats] = useState([]);
  const [filteredFlats, setFilteredFlats] = useState([]);
  const [sortOption, setSortOption] = useState('');
  const [filters, setFilters] = useState({
    price: '',
    rooms: '',
    type: '',
  });

  useEffect(() => {
    const fetchFlats = async () => {
      try {
        const response = await fetch('https://laba-kvp4.onrender.com/flats');
        const data = await response.json();
        setFlats(data);
        setFilteredFlats(data);
      } catch (error) {
        console.error('Помилка при завантаженні квартир з бекенду:', error);
      }
    };

    fetchFlats();
  }, []);

  const applyFilters = () => {
    let updatedFlats = [...flats];

    if (filters.price) {
      const [min, max] = filters.price.split('-').map(Number);
      updatedFlats = updatedFlats.filter(
        (flat) => Number(flat.price) >= min && Number(flat.price) <= max
      );
    }
    if (filters.rooms) {
      updatedFlats = updatedFlats.filter((flat) => Number(flat.rooms) === Number(filters.rooms));
    }
    if (filters.type) {
      updatedFlats = updatedFlats.filter((flat) => flat.type === filters.type);
    }

    setFilteredFlats(updatedFlats);
  };

  const handleSortChange = (e) => {
    const value = e.target.value;
    setSortOption(value);
    let sortedFlats = [...filteredFlats];
    if (value === '1') {
      sortedFlats.sort((a, b) => a.price - b.price);
    } else if (value === '2') {
      sortedFlats.sort((a, b) => b.price - a.price);
    } else if (value === '3') {
      sortedFlats.sort((a, b) => a.rooms - b.rooms);
    } else if (value === '4') {
      sortedFlats.sort((a, b) => b.rooms - a.rooms);
    }
    setFilteredFlats(sortedFlats);
  };

  return (
    <main className="main">
      <section className="search section" id="search">
        <div className="search__container container">
          <h2>Знайди своє житло</h2>
          <div className="select__container">
            <select
              className="select"
              onChange={(e) =>
                setFilters({
                  ...filters,
                  price: e.target.value,
                })
              }
            >
              <option value="">Ціна</option>
              <option value="1000-2000">1000-2000</option>
              <option value="2000-3000">2000-3000</option>
              <option value="3000-4000">3000-4000</option>
              <option value="4000-5000">4000-5000</option>
            </select>
            <select
              className="select"
              onChange={(e) =>
                setFilters({
                  ...filters,
                  rooms: e.target.value,
                })
              }
            >
              <option value="">Кількість кімнат</option>
              <option value="1">1</option>
              <option value="2">2</option>
              <option value="3">3</option>
              <option value="4">4</option>
            </select>
            <select
              className="select"
              onChange={(e) =>
                setFilters({
                  ...filters,
                  type: e.target.value,
                })
              }
            >
              <option value="">Тип квартири</option>
              <option value="Сімейні">Сімейні</option>
              <option value="Романтичні">Романтичні</option>
              <option value="Бізнес">Бізнес</option>
              <option value="Релакс">Релакс</option>
            </select>
            <button className="button search__button" onClick={applyFilters}>
              Пошук
            </button>
          </div>
        </div>
      </section>

      <section className="found section" id="found">
        <div className="results__container container">
          <div className="results__title">
            <p>Знайдено {filteredFlats.length} квартир</p>
            <select className="select" value={sortOption} onChange={handleSortChange}>
              <option value="">Сортування</option>
              <option value="1">За зростанням ціни</option>
              <option value="2">За спаданням ціни</option>
              <option value="3">За зростанням кімнат</option>
              <option value="4">За спаданням кімнат</option>
            </select>
          </div>
          <div className="found__container">
            {filteredFlats.map((flat) => (
              <FlatCard key={flat.id} flat={flat} />
            ))}
          </div>
        </div>
      </section>
    </main>
  );
};

function Available() {
  return (
    <>
      <Header />
      <AvailableData />
      <Footer />
    </>
  );
}

export default Available;
