import React from 'react';
import { Link } from 'react-router-dom';

const BookedList = ({ bookings, flats, userEmail, refreshBookings }) => {
  const getFlatById = (id) => flats.find((flat) => flat.id === id);

  const formatDate = (isoString) => {
    const date = new Date(isoString);
    return date.toLocaleDateString('uk-UA', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    });
  };

  const cancelBooking = async (bookingId) => {
    try {
      await fetch(`https://laba-kvp4.onrender.com/bookings/${bookingId}`, {
        method: 'DELETE',
      });
      refreshBookings(userEmail);
    } catch (error) {
      console.error('Помилка при видаленні бронювання через бекенд:', error);
    }
  };

  return (
    <div className="booked__apartments">
      {bookings.length === 0 ? (
        <p>Немає активних бронювань.</p>
      ) : (
        bookings.map((booking) => {
          const flat = getFlatById(booking.flatId);
          if (!flat) return null;

          return (
            <div key={booking.id} className="booked__card">
              <Link to={`/apartment/${flat.id}`} className="booked__link">
                <div className="booked__info">
                  <img
                    src={process.env.PUBLIC_URL + flat.images[0]}
                    className="booked__img"
                    alt="Квартира"
                  />
                  <h3 className="booked__street">{flat.location}</h3>
                  <p className="booked__dates">
                    {formatDate(booking.start)} — {formatDate(booking.end)}
                  </p>
                </div>
              </Link>
              <button className="button booked__cancel" onClick={() => cancelBooking(booking.id)}>
                Відмінити
              </button>
            </div>
          );
        })
      )}
    </div>
  );
};

export default BookedList;
