import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import DatePicker from 'react-datepicker';
import { registerLocale } from 'react-datepicker';
import uk from 'date-fns/locale/uk';
import 'react-datepicker/dist/react-datepicker.css';
import '../css/style.css';
import { useNavigate } from 'react-router-dom';

registerLocale('uk', uk);

const FlatCard = ({ flat }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);
  const [bookedDates, setBookedDates] = useState([]);
  const [totalPrice, setTotalPrice] = useState(0);
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      fetch('https://laba-kvp4.onrender.com/profile', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
        .then((res) => res.json())
        .then((data) => setUser(data))
        .catch(() => setUser(null));
    }
  }, []);

  useEffect(() => {
    const fetchBookings = async () => {
      try {
        const res = await fetch(`https://laba-kvp4.onrender.com/bookings/flat/${flat.id}`);
        const data = await res.json();

        if (!res.ok) {
          throw new Error(data.error || 'Помилка при завантаженні бронювань');
        }

        const formatted = data.map((b) => ({
          start: new Date(b.start),
          end: new Date(b.end),
        }));
        setBookedDates(formatted);
      } catch (error) {
        console.error('Помилка:', error);
      }
    };

    fetchBookings();
  }, [flat.id]);

  const handleBooking = async () => {
    const token = localStorage.getItem('token');
    if (startDate && endDate && token) {
      try {
        const res = await fetch('https://laba-kvp4.onrender.com/bookings', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            flatId: flat.id,
            start: startDate.toISOString(),
            end: endDate.toISOString(),
          }),
        });

        const data = await res.json();

        if (!res.ok) {
          alert(data.error || 'Помилка при бронюванні');
          return;
        }

        const days = Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24));
        setBookedDates((prev) => [
          ...prev,
          {
            start: startDate,
            end: endDate,
          },
        ]);
        setTotalPrice(days * flat.price);
        alert('Бронювання успішне!');
        setIsModalOpen(false);
        setStartDate(null);
        setEndDate(null);
      } catch (error) {
        alert('Щось пішло не так при збереженні бронювання.');
      }
    } else {
      alert('Вам потрібно увійти, щоб забронювати.');
    }
  };

  const getExcludedDates = () => {
    return bookedDates.flatMap(({ start, end }) => {
      const dates = [];
      let current = new Date(start);
      while (current <= end) {
        dates.push(new Date(current));
        current.setDate(current.getDate() + 1);
      }
      return dates;
    });
  };

  return (
    <div className="found__card">
      <Link to={`/apartment/${flat.id}`} className="found__link">
        <img src={process.env.PUBLIC_URL + flat.images[0]} className="found__img" alt="Apartment" />
        <div className="found__data">
          <h2 className="found__title">
            <i className="bx bx-map"></i>
            {flat.location}
          </h2>
          <h2 className="found__rooms">
            <i className="bx bx-building"></i>
            {flat.rooms} кімнати
          </h2>
          <h2 className="found__type">
            <i className="bx bx-home-alt-2"></i>
            {flat.type}
          </h2>
          <h2 className="found__price">
            <i className="bx bx-purchase-tag"></i>
            {flat.price} грн/доба
          </h2>
        </div>
      </Link>
      <button
        className={`button found__button ${!user ? 'disabled' : ''}`}
        onClick={() => user && setIsModalOpen(true)}
        style={{
          backgroundColor: !user ? '#ccc' : '',
          color: !user ? '#000000' : '',
          boxShadow: !user ? 'none' : '',
          fontSize: !user ? '1rem' : '',
          fontWeight: !user ? '600' : '',
          cursor: !user ? 'default' : '',
        }}
      >
        {!user ? 'Увійдіть, щоб забронювати' : 'Забронювати'}
      </button>
      {isModalOpen && (
        <div className="modal">
          <div className="modal-content">
            <h3>Оберіть дати бронювання</h3>
            <DatePicker
              locale="uk"
              selected={startDate}
              onChange={([start, end]) => {
                setStartDate(start);
                setEndDate(end);
              }}
              startDate={startDate}
              endDate={endDate}
              selectsRange
              excludeDates={getExcludedDates()}
              minDate={new Date()}
              placeholderText="Оберіть діапазон дат"
              dateFormat="dd.MM.yyyy"
              isClearable
            />
            {startDate && endDate ? (
              <p>
                Вартість: {Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24)) * flat.price}{' '}
                грн
              </p>
            ) : (
              <p>Не обрано дат</p>
            )}
            <div className="modal__actions">
              <button
                className="modal-button button"
                onClick={handleBooking}
                disabled={!startDate || !endDate || startDate.getTime() === endDate.getTime()}
              >
                Підтвердити
              </button>
              <button className="modal-button button" onClick={() => setIsModalOpen(false)}>
                Скасувати
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FlatCard;
