import React, { useEffect, useState } from 'react';
import '../css/style.css';
import Footer from '../components/Footer';
import Header from '../components/Header';
import BookedList from '../components/BookedList';

const Flats = () => {
  const [bookings, setBookings] = useState([]);
  const [userEmail, setUserEmail] = useState('');
  const [flats, setFlats] = useState([]);

  useEffect(() => {
    const token = localStorage.getItem('token');

    if (!token) return;

    const fetchUserData = async () => {
      try {
        const res = await fetch('https://laba-kvp4.onrender.com/profile', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        const data = await res.json();
        if (res.ok) {
          setUserEmail(data.email);
          fetchBookings(data.email, token);
          fetchFlats(token);
        } else {
          console.error('Помилка авторизації:', data.error);
        }
      } catch (err) {
        console.error('Помилка при отриманні профілю:', err);
      }
    };

    fetchUserData();
  }, []);

  const fetchBookings = async (email, token) => {
    try {
      const res = await fetch(`https://laba-kvp4.onrender.com/bookings?email=${email}`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const data = await res.json();
      setBookings(data);
    } catch (err) {
      console.error('Помилка завантаження бронювань:', err);
    }
  };

  const cancelBooking = async (bookingId) => {
    try {
      await fetch(`https://laba-kvp4.onrender.com/bookings/${bookingId}`, {
        method: 'DELETE',
      });
      fetchBookings(userEmail);
    } catch (error) {
      console.error('Помилка при видаленні бронювання через бекенд:', error);
    }
  };

  const fetchFlats = async () => {
    try {
      const response = await fetch('https://laba-kvp4.onrender.com/flats');
      const data = await response.json();
      setFlats(data);
    } catch (error) {
      console.error('Помилка завантаження квартир з бекенду:', error);
    }
  };

  return (
    <main className="main">
      <section className="booked section" id="booked">
        <div className="booked__container container">
          <div className="booked__info">
            <h1 className="user__email">Користувач: {userEmail || 'Гість'}</h1>
            <h2 className="booked__title">Мої бронювання</h2>
          </div>
          <BookedList
            bookings={bookings}
            flats={flats}
            userEmail={userEmail}
            cancelBooking={cancelBooking}
            refreshBookings={() => fetchBookings(userEmail)}
          />
        </div>
      </section>
    </main>
  );
};

function Booked() {
  return (
    <div className="app">
      <Header />
      <Flats />
      <Footer />
    </div>
  );
}

export default Booked;
